package com.example.it_canteen;
import android.content.Intent; import android.os.Bundle; import android.view.Menu; import android.view.MenuItem; import android.view.View; import android.widget.Button; import android.widget.TextView; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { Button Dhokla,Khaman,Patra,Khandvi,Idala,Idli,Dhosa,Reset,Next; TextView ShowOrder; int Dhoklacount=0,Khamancount=0,Patracount=0,Khandvicount=0,Idalacount=0,Idlicount=0,Dhosacount=0; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);Dhokla=findViewById(R.id.btn_dhokla);Khaman=findViewById(R.id.btn_khaman);Patra=findViewById(R.id.btn_patra);Khandvi=findViewById(R.id.btn_khandvi);Idala=findViewById(R.id.btn_idala);Idli=findViewById(R.id.btn_idli);Dhosa=findViewById(R.id.btn_dhosa);ShowOrder=findViewById(R.id.showorder);Reset=findViewById(R.id.btn_reset);Next=findViewById(R.id.next);View.OnClickListener l=v->{if(v==Dhokla)Dhoklacount++;else if(v==Khaman)Khamancount++;else if(v==Patra)Patracount++;else if(v==Khandvi)Khandvicount++;else if(v==Idala)Idalacount++;else if(v==Idli)Idlicount++;else Dhosacount++;showOrder();};Dhokla.setOnClickListener(l);Khaman.setOnClickListener(l);Patra.setOnClickListener(l);Khandvi.setOnClickListener(l);Idala.setOnClickListener(l);Idli.setOnClickListener(l);Dhosa.setOnClickListener(l);Reset.setOnClickListener(v->{Dhoklacount=Khamancount=Patracount=Khandvicount=Idalacount=Idlicount=Dhosacount=0;ShowOrder.setText("Your Order will be shown here :");});Next.setOnClickListener(v->{Intent i=new Intent(this,review_order.class);i.putExtra("finalorder",orderText());startActivity(i);});}private String orderText(){int total=Dhoklacount+Khamancount+Patracount+Khandvicount+Idalacount+Idlicount+Dhosacount;return "Dhokla: "+Dhoklacount+"\nKhaman: "+Khamancount+"\nPatra: "+Patracount+"\nKhandvi: "+Khandvicount+"\nIdala: "+Idalacount+"\nIdli: "+Idlicount+"\nDhosa: "+Dhosacount+"\n----------------\nTotal: "+(total*50);}private void showOrder(){ShowOrder.setText("Your Order is\n"+orderText());}@Override public boolean onCreateOptionsMenu(Menu menu){getMenuInflater().inflate(R.menu.option_menu,menu);return true;}@Override public boolean onOptionsItemSelected(@NonNull MenuItem item){if(item.getItemId()==R.id.cart_icon){Intent i=new Intent(this,review_order.class);i.putExtra("finalorder",orderText());startActivity(i);return true;}return super.onOptionsItemSelected(item);}}
